// def method(self, v: Box) -> None:
//     p = make_mixed(1, v)
//     a = p[0]
//     a2 = p[0]
//     # method: 'a' still reads the old element, so the new one takes a slot.
//     p = make_mixed(9, v)  # tpyc: ok
//     a.n += 100
//     print("method", a2.n, p[0].n)
inline void Holder::method(Box& v) const {
    auto __tup_1 = ::tpyapp::main::make_mixed(1, v);
    Box __slot_1 = std::move(std::get<0>(__tup_1));
    std::tuple<Box*, Box*> p{&__slot_1, std::get<1>(__tup_1)};
    Box& a = (*std::get<0>(p));
    Box& a2 = (*std::get<0>(p));
    std::optional<Box> __slot_2;
    auto __tup_2 = ::tpyapp::main::make_mixed(9, v);
    std::get<0>(p) = &*(__slot_2 = std::move(std::get<0>(__tup_2)));
    std::get<1>(p) = std::get<1>(__tup_2);
    a.n = ::tpy::add_check<int32_t>(a.n, 100);
    std::cout << "method" << " " << a2.n << " " << std::get<0>(p)->n << "\n" << ::tpy::check_signals;
}

// def __init__(self, v: Box) -> None:
//     p = make_mixed(1, v)
//     a = p[0]
//     a2 = p[0]
//     # constructor: 'a' still reads the old element, so the new one takes
//     # a slot of its own.
//     p = make_mixed(9, v)  # tpyc: ok
//     a.n += 100
//     self.seen = a2.n * 100 + p[0].n
inline Built::Built(Box& v) {
    auto __tup_1 = ::tpyapp::main::make_mixed(1, v);
    Box __slot_1 = std::move(std::get<0>(__tup_1));
    std::tuple<Box*, Box*> p{&__slot_1, std::get<1>(__tup_1)};
    Box& a = (*std::get<0>(p));
    Box& a2 = (*std::get<0>(p));
    std::optional<Box> __slot_2;
    auto __tup_2 = ::tpyapp::main::make_mixed(9, v);
    std::get<0>(p) = &*(__slot_2 = std::move(std::get<0>(__tup_2)));
    std::get<1>(p) = std::get<1>(__tup_2);
    a.n = ::tpy::add_check<int32_t>(a.n, 100);
    this->seen = (::tpy::add_check<int32_t>((::tpy::mul_check<int32_t>(a2.n, 100)), std::get<0>(p)->n));
}

